  const modalTitle=modal?.type==="review"?"Faire le point sur ma saisie":modal?.type==="favorites"?"Vos favoris":modal?.type==="favorite"?(modal.item?"Modifier le favori":"Créer un favori"):modal?.type==="balance"?"Ajuster le solde":modal?.type==="filters"?"Filtrer les opérations":modal?.type==="navigation"?"Plus dans Pécule":modal?.type==="reconcile"?`Rapprocher ${b.accounts.find(a=>a.id===modal.accountId)?.name??"le compte"}`:modal?.type==="bulk"?"Modifier plusieurs opérations":modal?.type==="match-transfers"?"Associer des virements internes":modal?.type==="imports"?"Vos imports bancaires":modal?.type==="actions"?"Une action, en un geste.":modal?.type==="transaction"?(modal.item?"Le détail de l’opération":"Ajouter une opération"):modal?.type==="account"?(modal.item?"Modifier le compte":"Un nouveau compte"):modal?.type==="rule"?(modal.item?"Modifier la récurrence":modal.proposal?"Vérifier cette récurrence":"Prévoir une récurrence"):modal?.type==="goal"?(modal.item?"Modifier votre objectif":"Un projet à concrétiser"):modal?.type==="transfer"?"Enregistrer un virement":modal?.type==="contribution"?"Faire grandir votre projet":modal?.type==="import"?"Importer vos opérations":modal?.type==="start"?"Bienvenue chez vous.":modal?.type==="calculation"?"Un disponible qui a du sens.":modal?.type==="install"?"PECULE, à portée de main.":modal?.type==="confirm"?modal.title:"";
