    if(modal.type==="account"){const balance=amount("balance");if(balance===null){setError("Indiquez un solde valide.");return;}const item:Account={...modal.item,id:modal.item?.id??uid(),name:v("name"),bank:v("bank"),type:v("type") as Account["type"],openingBalance:balance,openingDate:v("date"),color:v("color")};next.accounts=editItem(next.accounts,item);success=await save(next);}
    if(modal.type==="transaction"){const n=amount("amount");if(n===null||n<=0){setError("Le montant doit être supérieur à zéro.");return;}const old=modal.item;const item:Transaction={...old,id:old?.id??uid(),label:v("label"),amount:n*(v("direction")==="expense"?-1:1),date:v("date"),accountId:v("account"),category:v("category"),note:v("note"),...(v("merchantId")?{merchantId:v("merchantId")} : {}),...(v("customIconUrl")?{customIconUrl:v("customIconUrl")}:{}),...(old?.ruleId?{ruleId:old.ruleId}:{})};if(old?.ruleId&&old.date!==item.date){const r=next.rules.find(r=>r.id===old.ruleId);if(r&&!r.excludedDates.includes(old.date))r.excludedDates.push(old.date);}const acc=next.accounts.find(a=>a.id===item.accountId);if(acc&&item.balanceIncluded&&item.date>acc.openingDate){setError("Une opération historique doit rester comprise dans la date du solde de référence.");return;}if(acc&&!item.balanceIncluded&&item.date<acc.openingDate){setError("Cette date précède le solde de référence du compte. Modifiez d’abord sa date de référence.");return;}if(!v("customIconUrl"))delete item.customIconUrl;if(!v("merchantId"))delete item.merchantId;next.transactions=editItem(next.transactions,item);next.settings.capture={...next.settings.capture,lastAccountId:item.accountId};if(f.get("saveFavorite")){const favorites=next.settings.capture.favorites??[];if(favorites.length>=20){setError("La limite de vingt favoris est atteinte. Gérez vos favoris avant d’en ajouter un.");return;}next.settings.capture.favorites=[...favorites,favoriteFromTransaction(item,uid())];}if(f.get("rememberCategory")){try{next.settings.categoryRules=rememberCategory(next.settings.categoryRules,item.label,item.merchantId,item.amount>0,item.category);}catch(cause){setError(cause instanceof Error?cause.message:"Impossible de mémoriser cette catégorie.");return;}}pendingCapture.current=!modal.item&&(e.nativeEvent as SubmitEvent).submitter instanceof HTMLButtonElement&&((e.nativeEvent as SubmitEvent).submitter as HTMLButtonElement).value==="continue"?{type:"transaction",accountId:item.accountId,initialDate:item.date,direction:item.amount>0?"income":"expense",sequence:(modal.sequence??0)+1,returnReviewDate:modal.returnReviewDate,returnAccountId:modal.returnAccountId}:null;success=await save(next);}
    if(modal.type==="rule"){const n=amount("amount");if(n===null||n<=0){setError("Indiquez un montant supérieur à zéro.");return;}if(v("end")&&v("end")<v("date")){setError("La date de fin doit suivre la date de début.");const control=e.currentTarget.querySelector<HTMLInputElement>('input[name="end"]');if(control)revealFormControl(control);return;}const item:Rule={id:modal.item?.id??uid(),label:v("label"),amount:n*(v("direction")==="expense"?-1:1),accountId:v("account"),category:v("category"),startDate:v("date"),endDate:v("end"),frequency:v("frequency") as Rule["frequency"],timing:v("timing") as Rule["timing"],day:Number(v("day")),active:modal.item?.active??true,holidays:v("holidays") as Rule["holidays"],excludedDates:modal.item?.excludedDates??[],...(v("merchantId")?{merchantId:v("merchantId")} : {}),...(v("customIconUrl")?{customIconUrl:v("customIconUrl")}:{})};if(modal.sourceTransactionId){try{const converted=convertTransactionToRecurring(next,modal.sourceTransactionId,item,today);next.rules=converted.rules;next.transactions=converted.transactions;}catch(error){setError(error instanceof Error?error.message:"Impossible de créer cette récurrence.");return;}}else next.rules=editItem(next.rules,item);success=await save(next,modal.sourceTransactionId?"Récurrence créée. L’opération d’origine est conservée.":undefined);}
    if(modal.type==="goal"){const target=amount("target"),saved=amount("saved"),monthly=amount("monthly");if(target===null||target<=0||saved===null||saved<0||monthly===null||monthly<0){setError("Vérifiez les montants de votre objectif.");return;}next.goals=editItem(next.goals,{id:modal.item?.id??uid(),name:v("name"),target,saved,monthly,color:v("color"),icon:v("icon"),deadline:v("deadline")});success=await save(next);}
