    {modal.type==="favorites"&&<CaptureFavorites budget={b} hidden={hidden} saving={saving} serverError={error} onCreate={()=>open({type:"favorite"})} onEdit={item=>open({type:"favorite",item})} onUse={openFavorite} save={save}/>}
    {modal.type==="favorite"&&<FavoriteEditor key={modalKey(modal)} draftKey={modalKey(modal)} budget={b} item={modal.item} saving={saving} serverError={error} save={save} onDone={()=>open({type:"favorites"})} onCancel={()=>open({type:"favorites"})} initialDirection={drafts?.get(modalKey(modal))?.direction?.[0] as Favorite["direction"]|undefined}/>}
    {modal.type==="balance"&&b.accounts.some(a=>a.id===modal.accountId)&&<AccountBalanceAdjustment key={modal.accountId} budget={b} accountId={modal.accountId} today={today} hidden={hidden} saving={saving} serverError={error} draftKey={modalKey(modal)} initialValue={drafts?.get(modalKey(modal))?.balance?.[0]??""} onCompare={balance=>{setReconciliationDrafts(previous=>({...previous,[modal.accountId]:{date:today,balance,checked:[],query:""}}));open({type:"reconcile",accountId:modal.accountId});}} onMissing={(difference,balance)=>{setReconciliationDrafts(previous=>({...previous,[modal.accountId]:{date:today,balance,checked:[],query:""}}));open({type:"transaction",accountId:modal.accountId,initialDate:today,initialAmount:Math.abs(difference),direction:difference>0?"income":"expense",returnAccountId:modal.accountId});}} save={save} onDone={()=>setModal(null)} onCancel={()=>setModal(null)}/>}
