    {modal.type==="reconcile"&&b.accounts.some(a=>a.id===modal.accountId)&&<BankReconciliation key={modal.accountId} budget={b} accountId={modal.accountId} today={today} hidden={hidden} saving={saving} serverError={error} initialDraft={reconciliationDrafts[modal.accountId]} onDraftChange={retainReconciliationDraft} save={save} onDone={()=>{setReconciliationDrafts(previous=>{const next={...previous};delete next[modal.accountId];return next;});setModal(null);}} onEdit={item=>open({type:"transaction",item,returnAccountId:modal.accountId})} onAdd={(date,amount)=>open({type:"transaction",direction:amount>0?"income":"expense",accountId:modal.accountId,initialDate:date,initialAmount:Math.abs(amount),returnAccountId:modal.accountId})} onEditAccount={()=>open({type:"account",item:b.accounts.find(a=>a.id===modal.accountId),returnAccountId:modal.accountId})} onTransfers={()=>open({type:"match-transfers",returnAccountId:modal.accountId})}/>}
